// A controlled input: the handler updates state from what was typed.
const input = { value: "" };
let shown = "";
input.onChange = function (v) { shown = "Hi " + v; };
function type(input, text) {
  input.value = text;
  input.onChange(input.value);
}
type(input, "Ada");
console.log(shown);

