// preventDefault stops the reload; the handler does the rest.
let reloaded = true;
const form = {
  onSubmit: function (e) { e.preventDefault(); console.log("saved"); }
};
function submit(form) {
  const event = { preventDefault: function () { reloaded = false; } };
  form.onSubmit(event);
}
submit(form);
console.log(reloaded);

